    liveUv.x >= 0.0 && liveUv.x <= 1.0 && liveUv.y >= 0.0 && liveUv.y <= 1.0,
    is_inside_screen(liveUv, uni.aspect, neutralExtent, uni.angle),
    uni.liveZoomFactor < 1.0
